const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const signature = String(headers['x-hub-signature-256'] || '');
const rawBody = item.json.rawBody || item.binary?.data?.data && Buffer.from(item.binary.data.data, 'base64').toString('utf8');
const appSecret = $env.META_APP_SECRET;

if (!appSecret || !rawBody || !signature) {
  return [{ json: { valid: false, reason: 'missing_signature_or_body' } }];
}

const expected = 'sha256=' + crypto.createHmac('sha256', appSecret).update(rawBody).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(signature);
const valid = a.length === b.length && crypto.timingSafeEqual(a, b);

let payload = null;
try { payload = JSON.parse(rawBody); } catch (e) { payload = null; }

return [{ json: { valid, reason: valid ? 'ok' : 'bad_signature', payload } }];

const payload = $json.payload || {};
const change = payload.entry?.[0]?.changes?.[0]?.value || {};
const message = change.messages?.[0];
if (!message) {
  return [{ json: { skip: true, reason: 'sin_mensaje' } }];
}
const crudo = String(message.from || '');
const digitos = crudo.replace(/\D/g, '');
const e164 = digitos.length === 10 ? `+52${digitos}` : digitos.startsWith('52') ? `+${digitos}` : `+${digitos}`;
const texto = message.text?.body || message.type || '';
return [{
  json: {
    skip: false,
    message_id: message.id,
    e164,
    telefono_normalizado: digitos,
    texto,
    ocurrido_at: message.timestamp ? new Date(Number(message.timestamp) * 1000).toISOString() : new Date().toISOString()
  }
}];
